			require.NoError(t, err)
			err = os.WriteFile(filepath.Join(e.Cd, "badheader.pem"), badHeaderBytes, 0600)
			require.NoError(t, err)
			err = os.WriteFile(filepath.Join(e.Cd, "password.txt"), []byte("password"), 0600)
			require.NoError(t, err)
